const upsertExternalIssueSource = `-- name: UpsertExternalIssueSource :one

INSERT INTO external_issue_source (
    workspace_id, provider, instance_key, credential_id,
    repository_external_id, repository_full_path, target_project_id,
    filter, mode, state, configured_by_user_id
) VALUES (
    $1, $2, $3, $9,
    $4, $5, $10,
    $6, $7, $8, $11
)
ON CONFLICT (workspace_id, provider, instance_key, repository_external_id) DO UPDATE SET
    credential_id = EXCLUDED.credential_id,
    repository_full_path = EXCLUDED.repository_full_path,
    target_project_id = EXCLUDED.target_project_id,
    filter = EXCLUDED.filter,
    mode = EXCLUDED.mode,
    state = EXCLUDED.state,
    updated_at = now()
RETURNING id, workspace_id, provider, instance_key, credential_id, repository_external_id, repository_full_path, target_project_id, filter, mode, state, configured_by_user_id, last_reconciled_at, next_reconcile_at, created_at, updated_at
`

type UpsertExternalIssueSourceParams struct {
	WorkspaceID          pgtype.UUID `json:"workspace_id"`
	Provider             string      `json:"provider"`
	InstanceKey          string      `json:"instance_key"`
	RepositoryExternalID string      `json:"repository_external_id"`
	RepositoryFullPath   string      `json:"repository_full_path"`
	Filter               []byte      `json:"filter"`
	Mode                 string      `json:"mode"`
	State                string      `json:"state"`
	CredentialID         pgtype.UUID `json:"credential_id"`
	TargetProjectID      pgtype.UUID `json:"target_project_id"`
	ConfiguredByUserID   pgtype.UUID `json:"configured_by_user_id"`
}

// =====================
// External Issue Source
// =====================
// Create or reuse the one source per (workspace, provider, instance, remote
// repo). Reselecting the same repo (e.g. from another project) reuses the row
// and refreshes its mutable binding/display fields rather than creating a
// competing source.
func (q *Queries) UpsertExternalIssueSource(ctx context.Context, arg UpsertExternalIssueSourceParams) (ExternalIssueSource, error) {
	row := q.db.QueryRow(ctx, upsertExternalIssueSource,
		arg.WorkspaceID,
		arg.Provider,
		arg.InstanceKey,
		arg.RepositoryExternalID,
		arg.RepositoryFullPath,
		arg.Filter,
		arg.Mode,
		arg.State,
		arg.CredentialID,
		arg.TargetProjectID,
		arg.ConfiguredByUserID,
	)
	var i ExternalIssueSource
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.Provider,
		&i.InstanceKey,
		&i.CredentialID,
		&i.RepositoryExternalID,
		&i.RepositoryFullPath,
		&i.TargetProjectID,
		&i.Filter,
		&i.Mode,
		&i.State,
		&i.ConfiguredByUserID,
		&i.LastReconciledAt,
		&i.NextReconcileAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const upsertExternalIssueSyncRunItem = `-- name: UpsertExternalIssueSyncRunItem :one
INSERT INTO external_issue_sync_run_item (run_id, workspace_id, external_issue_id, outcome)
VALUES ($1, $2, $3, $4)
ON CONFLICT (run_id, external_issue_id) DO UPDATE SET
    outcome = CASE
        WHEN array_position(ARRAY['failed','skipped','conflict','updated','imported'], EXCLUDED.outcome)
           > array_position(ARRAY['failed','skipped','conflict','updated','imported'], external_issue_sync_run_item.outcome)
        THEN EXCLUDED.outcome
        ELSE external_issue_sync_run_item.outcome
    END
RETURNING (xmax = 0) AS inserted
`

type UpsertExternalIssueSyncRunItemParams struct {
	RunID           pgtype.UUID `json:"run_id"`
	WorkspaceID     pgtype.UUID `json:"workspace_id"`
	ExternalIssueID string      `json:"external_issue_id"`
	Outcome         string      `json:"outcome"`
}

// Record (run, remote issue) -> outcome on stable identity. inserted=true only
// when this is the first time the issue was accounted in this run, so the caller
// bumps counts exactly once even if a re-fetched page replays the issue. On
// replay the outcome is kept STICKY by precedence (failed < skipped < conflict <
// updated < imported): an already-imported issue re-seen as a skipped no-op on
// resume keeps "imported", and a prior "failed" can be upgraded on retry —
// neither double-counts nor reclassifies a committed create as a skip.
func (q *Queries) UpsertExternalIssueSyncRunItem(ctx context.Context, arg UpsertExternalIssueSyncRunItemParams) (bool, error) {
	row := q.db.QueryRow(ctx, upsertExternalIssueSyncRunItem,
		arg.RunID,
		arg.WorkspaceID,
		arg.ExternalIssueID,
		arg.Outcome,
	)
	var inserted bool
	err := row.Scan(&inserted)
	return inserted, err
}
